window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bb43c64332f230dc"]={"versions": [{"id": "FIG-bb43c64332f230dc", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Hierarchie der Software-Komponententypen im AUTOSAR-SoftwareComponentTemplate. Das Diagramm spezifiziert die Vererbungsstruktur ausgehend von <code>ComponentType</code> sowie die Instanziierungs- und Kompositionsbeziehungen über <code>ComponentPrototype</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Abstrakte Metaklasse als Basis für eigenständige Modellelemente.\n</li><li><code>Identifiable</code>: Basisklasse für identifizierbare Elemente mit Namen und Bezeichnern.\n</li><li><code>ComponentType</code> (Stereotyp <code>«atpType»</code>, erbt von <code>ARElement</code>): Abstrakter Basistyp aller Software-Komponenten.\n<ul class=\"fig-list\"><li>Spezialisierungen von <code>ComponentType</code>:\n<ul class=\"fig-list\"><li><code>AtomicSoftwareComponentType</code>: Basisklasse für atomare Software-Komponenten.\n</li><li><code>CalprmComponentType</code> (Stereotyp <code>«atpType»</code>): Komponententyp für Kalibrierparameter.\n</li><li><code>CompositionType</code> (Stereotyp <code>«atpType»</code>): Zusammengesetzter Komponententyp, der Sub-Komponenten aggregiert.\n</li></ul>\n</li><li>Spezialisierungen von <code>AtomicSoftwareComponentType</code>:\n<ul class=\"fig-list\"><li><code>SensorActuatorSoftwareComponentType</code>: Repräsentiert Sensor-/Aktor-Softwarekomponenten.\n</li><li><code>ServiceComponentType</code>: Repräsentiert Service-Komponenten.\n</li></ul>\n</li></ul>\n</li><li><code>ComponentPrototype</code> (Stereotyp <code>«atpPrototype»</code>, erbt von <code>Identifiable</code>): Repräsentiert das Vorkommen/die Instanz eines <code>ComponentType</code> innerhalb einer Komposition.\n</li><li>Assoziationen und Beziehungen:\n<ul class=\"fig-list\"><li>Komposition von <code>CompositionType</code> zu <code>ComponentPrototype</code>: Rolle <code>+component</code>, Multiplizität <code>1..*</code>.\n</li><li>Assoziation <code>«isOfType»</code> von <code>ComponentPrototype</code> (<code>*</code>) zu <code>ComponentType</code> (<code>1</code>, Rolle <code>+type</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Verhaltensabläufe. Die Laufzeitstruktur wird statisch durch die Typ-Prototyp-Instanziierung (<code>ComponentPrototype</code> referenziert über Rolle <code>+type</code> genau einen <code>ComponentType</code>) und die hierarchische Kapselung in <code>CompositionType</code> definiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>CalprmComponentType</code> ist ein eigenständiger <code>ComponentType</code> auf gleicher Hierarchieebene wie <code>AtomicSoftwareComponentType</code> und <code>CompositionType</code>.\n</li><li><code>CompositionType</code> enthält mindestens einen Prototyp (<code>1..*</code>), leere Kompositionen sind unzulässig.\n</li><li>Jeder <code>ComponentPrototype</code> verweist strikt auf genau einen konkreten <code>ComponentType</code> (<code>1</code>).\n</li></ul>"}, {"id": "FIG-40169b0a3277b260", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Hierarchie der Software-Komponententypen im AUTOSAR-SoftwareComponentTemplate. Das Diagramm spezifiziert die Vererbungsstruktur ausgehend von <code>ComponentType</code> sowie die Instanziierungs- und Kompositionsbeziehungen über <code>ComponentPrototype</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Abstrakte Metaklasse als Basis für eigenständige Modellelemente.\n</li><li><code>Identifiable</code>: Basisklasse für identifizierbare Elemente mit Namen und Bezeichnern.\n</li><li><code>ComponentType</code> (Stereotyp <code>«atpType»</code>, erbt von <code>ARElement</code>): Abstrakter Basistyp aller Software-Komponenten.\n<ul class=\"fig-list\"><li>Spezialisierungen von <code>ComponentType</code>:\n<ul class=\"fig-list\"><li><code>AtomicSoftwareComponentType</code>: Basisklasse für atomare Software-Komponenten.\n</li><li><code>CalprmComponentType</code> (Stereotyp <code>«atpType»</code>): Komponententyp für Kalibrierparameter.\n</li><li><code>CompositionType</code> (Stereotyp <code>«atpType»</code>): Zusammengesetzter Komponententyp, der Sub-Komponenten aggregiert.\n</li></ul>\n</li><li>Spezialisierungen von <code>AtomicSoftwareComponentType</code>:\n<ul class=\"fig-list\"><li><code>ApplicationSoftwareComponentType</code>: Repräsentiert Anwendungskomponenten.\n</li><li><code>SensorActuatorSoftwareComponentType</code>: Repräsentiert Sensor-/Aktor-Softwarekomponenten.\n</li><li><code>ServiceComponentType</code> (Stereotyp <code>«atpType»</code>): Repräsentiert Basessoftware-nahe Service-Komponenten.\n</li><li><code>EcuAbstractionComponentType</code>: Repräsentiert ECU-Abstraktions-Komponenten.\n</li><li><code>ComplexDeviceDriverComponentType</code>: Repräsentiert komplexe Treiberkomponenten (CDD).\n</li></ul>\n</li></ul>\n</li><li><code>ComponentPrototype</code> (Stereotyp <code>«atpPrototype»</code>, erbt von <code>Identifiable</code>): Repräsentiert das Vorkommen/die Instanz eines <code>ComponentType</code> innerhalb einer Komposition.\n</li><li>Assoziationen und Beziehungen:\n<ul class=\"fig-list\"><li>Komposition von <code>CompositionType</code> zu <code>ComponentPrototype</code>: Rolle <code>+component</code>, Multiplizität <code>1..*</code>.\n</li><li>Assoziation <code>«isOfType»</code> von <code>ComponentPrototype</code> (<code>*</code>) zu <code>ComponentType</code> (<code>1</code>, Rolle <code>+type</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Verhaltensabläufe. Die Laufzeitstruktur wird statisch durch die Typ-Prototyp-Instanziierung (<code>ComponentPrototype</code> referenziert über Rolle <code>+type</code> genau einen <code>ComponentType</code>) und die hierarchische Kapselung in <code>CompositionType</code> definiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>CalprmComponentType</code> ist ein eigenständiger <code>ComponentType</code> auf gleicher Hierarchieebene wie <code>AtomicSoftwareComponentType</code> und <code>CompositionType</code>.\n</li><li><code>AtomicSoftwareComponentType</code> subsumiert spezialisierte Typen für Applikation, Sensor/Aktor, BSW-Services, ECU-Abstraktion und CDDs.\n</li><li><code>CompositionType</code> verlangt mindestens einen enthaltenen Prototyp (<code>1..*</code>).\n</li><li>Jeder <code>ComponentPrototype</code> verweist strikt auf genau einen konkreten <code>ComponentType</code> (<code>1</code>).\n</li></ul>"}, {"id": "FIG-ee4a3a245776445e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Hierarchie der Software-Komponententypen im AUTOSAR-SoftwareComponentTemplate. Das Diagramm spezifiziert die Vererbungsstruktur ausgehend von <code>ComponentType</code> sowie die Instanziierungs- und Kompositionsbeziehungen über <code>ComponentPrototype</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Abstrakte Metaklasse als Basis für eigenständige Modellelemente.\n</li><li><code>Identifiable</code>: Basisklasse für identifizierbare Elemente mit Namen und Bezeichnern.\n</li><li><code>ComponentType</code> (Stereotyp <code>«atpType»</code>, erbt von <code>ARElement</code>): Abstrakter Basistyp aller Software-Komponenten.\n<ul class=\"fig-list\"><li>Spezialisierungen von <code>ComponentType</code>:\n<ul class=\"fig-list\"><li><code>AtomicSoftwareComponentType</code>: Basisklasse für atomare Software-Komponenten.\n</li><li><code>CalprmComponentType</code> (Stereotyp <code>«atpType»</code>): Komponententyp für Kalibrierparameter.\n</li><li><code>CompositionType</code> (Stereotyp <code>«atpType»</code>): Zusammengesetzter Komponententyp, der Sub-Komponenten aggregiert.\n</li></ul>\n</li><li>Spezialisierungen von <code>AtomicSoftwareComponentType</code>:\n<ul class=\"fig-list\"><li><code>NvBlockSwComponentType</code>: Repräsentiert Nichtflüchtige-Speicherblock-Softwarekomponenten.\n</li><li><code>ApplicationSoftwareComponentType</code>: Repräsentiert Anwendungskomponenten.\n</li><li><code>SensorActuatorSoftwareComponentType</code>: Repräsentiert Sensor-/Aktor-Softwarekomponenten.\n</li><li><code>ServiceComponentType</code> (Stereotyp <code>«atpType»</code>): Repräsentiert Basessoftware-nahe Service-Komponenten.\n</li><li><code>EcuAbstractionComponentType</code>: Repräsentiert ECU-Abstraktions-Komponenten.\n</li><li><code>ComplexDeviceDriverComponentType</code>: Repräsentiert komplexe Treiberkomponenten (CDD).\n</li></ul>\n</li></ul>\n</li><li><code>ComponentPrototype</code> (Stereotyp <code>«atpPrototype»</code>, erbt von <code>Identifiable</code>): Repräsentiert das Vorkommen/die Instanz eines <code>ComponentType</code> innerhalb einer Komposition.\n</li><li>Assoziationen und Beziehungen:\n<ul class=\"fig-list\"><li>Komposition von <code>CompositionType</code> zu <code>ComponentPrototype</code>: Rolle <code>+component</code>, Multiplizität <code>0..*</code>.\n</li><li>Assoziation <code>«isOfType»</code> von <code>ComponentPrototype</code> (<code>*</code>) zu <code>ComponentType</code> (<code>1</code>, Rolle <code>+type</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Verhaltensabläufe. Die Laufzeitstruktur wird statisch durch die Typ-Prototyp-Instanziierung (<code>ComponentPrototype</code> referenziert über Rolle <code>+type</code> genau einen <code>ComponentType</code>) und die hierarchische Kapselung in <code>CompositionType</code> definiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>CalprmComponentType</code> ist ein eigenständiger <code>ComponentType</code> auf gleicher Hierarchieebene wie <code>AtomicSoftwareComponentType</code> und <code>CompositionType</code>.\n</li><li>Durch die Kardinalität <code>0..*</code> an der Rolle <code>+component</code> darf ein <code>CompositionType</code> auch ohne enthaltene <code>ComponentPrototype</code>-Elemente modelliert werden.\n</li><li><code>AtomicSoftwareComponentType</code> umfasst auch <code>NvBlockSwComponentType</code> zur Anbindung von NVRAM-Blöcken.\n</li><li>Jeder <code>ComponentPrototype</code> verweist strikt auf genau einen konkreten <code>ComponentType</code> (<code>1</code>).\n</li></ul>"}], "trans": [{"from": "FIG-bb43c64332f230dc", "to": "FIG-40169b0a3277b260", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Hinzugefügte Spezialisierungen von <code>AtomicSoftwareComponentType</code>: <code>ApplicationSoftwareComponentType</code>, <code>EcuAbstractionComponentType</code> und <code>ComplexDeviceDriverComponentType</code>.\n</li><li><code>ServiceComponentType</code>: Stereotyp <code>«atpType»</code> ergänzt.\n</li></ul>"}, {"from": "FIG-40169b0a3277b260", "to": "FIG-ee4a3a245776445e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Hinzugefügte Spezialisierung von <code>AtomicSoftwareComponentType</code>: <code>NvBlockSwComponentType</code>.\n</li><li>Kompositions-Aggregation <code>CompositionType</code> zu <code>ComponentPrototype</code>: Kardinalität an der Rolle <code>+component</code> von <code>1..*</code> auf <code>0..*</code> geändert.\n</li></ul>"}]};
